function orchardPlots(grid) {
    const rows = grid.length;
    const cols = rows === 0 ? 0 : grid[0].length;
    const label = grid.map((row, r) => row.split("").map((cell, c) => cell === "T" ? r * cols + c : -1));
    let changed = true;
    while (changed) {
        changed = false;
        for (let r = 0; r < rows; r++) {
            for (let c = 0; c < cols; c++) {
                if (label[r][c] === -1)
                    continue;
                for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
                    const nr = r + dr;
                    const nc = c + dc;
                    if (nr < 0 || nc < 0 || nr >= rows || nc >= cols || label[nr][nc] === -1)
                        continue;
                    if (label[nr][nc] < label[r][c]) {
                        label[r][c] = label[nr][nc];
                        changed = true;
                    }
                }
            }
        }
    }
    const plots = new Set();
    for (const row of label)
        for (const value of row)
            if (value !== -1)
                plots.add(value);
    return plots.size;
}

function orchardPlots(grid) {
    const rows = grid.length;
    const cols = rows === 0 ? 0 : grid[0].length;
    const seen = new Set();
    let plots = 0;
    for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
            if (grid[r][c] !== "T" || seen.has(r * cols + c))
                continue;
            plots++;
            const stack = [r * cols + c];
            seen.add(r * cols + c);
            while (stack.length > 0) {
                const cell = stack.pop();
                const cr = Math.floor(cell / cols);
                const cc = cell % cols;
                for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
                    const nr = cr + dr;
                    const nc = cc + dc;
                    if (nr < 0 || nc < 0 || nr >= rows || nc >= cols || grid[nr][nc] !== "T")
                        continue;
                    const next = nr * cols + nc;
                    if (!seen.has(next)) {
                        seen.add(next);
                        stack.push(next);
                    }
                }
            }
        }
    }
    return plots;
}
